-- Rollback only before any commission policy, receipt, or earned snapshot exists.
BEGIN;SET LOCAL ROLE celebix_saas_owner;SET LOCAL lock_timeout='5s';
SELECT pg_advisory_xact_lock(hashtextextended('saas.accounting.release250',0));
LOCK TABLE saas.in_store_staff_grants,saas.in_store_sales,saas.accounting_cashier_commission_sales IN SHARE ROW EXCLUSIVE MODE;
DO $use$BEGIN IF EXISTS(SELECT 1 FROM saas.in_store_staff_grants WHERE commission_enabled OR commission_rate_bps<>0)OR EXISTS(SELECT 1 FROM saas.accounting_cashier_commission_sales)OR EXISTS(SELECT 1 FROM saas.in_store_operations WHERE operation_kind='set_staff_v6')OR EXISTS(SELECT 1 FROM saas.in_store_sales WHERE status IN('payment_pending','payment_received'))THEN RAISE EXCEPTION 'COMMISSION250_ROLLBACK_IN_USE';END IF;END $use$;
DO $functions$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting250_commission_guard()') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='daf5572c4d06cf651eea616751e55c77d9d705fcbe4196c9932b12f82e9a2424' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.accounting250_commission_guard()';END IF;
