 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_list_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='3f360ee77b9f085e5222a7ab884ff2b105e1edcf3c8ee6174b2688f7d9773782' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_list_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_recover_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='a19f7505e7e4744828004548859da49ccd36e3f61a363ed8713c4a12c02aa2da' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_recover_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_set_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean,boolean,integer)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='3dc299f8d88aab2adf58f00a1f0010195f7f5ac5385b4442776c03e0f90cdaa9' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_set_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean,boolean,integer)';END IF;
